body.script:
//
(function(){var body=document.body,nav=document.querySelector('.nav'),toggle=document.querySelector('.nav-toggle'),theme=document.querySelector('.theme-toggle'),year=document.getElementById('year');body.setAttribute('data-theme',localStorage.getItem('md-rasel-theme')||'green');if(theme)theme.addEventListener('click',function(){var next=body.getAttribute('data-theme')==='green'?'light':'green';body.setAttribute('data-theme',next);localStorage.setItem('md-rasel-theme',next)});if(year)year.textContent=new Date().getFullYear();if(toggle)toggle.addEventListener('click',function(){var open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});document.querySelectorAll('.nav-links a').forEach(function(link){link.addEventListener('click',function(){nav.classList.remove('open')})});var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.12});document.querySelectorAll('.reveal').forEach(function(item){observer.observe(item)});var form=document.getElementById('chat-form'),input=document.getElementById('chat-input'),messages=document.querySelector('.chat-messages');if(form&&input&&messages)form.addEventListener('submit',function(event){event.preventDefault();var text=input.value.trim();if(!text)return;var user=document.createElement('div');user.className='chat-bubble bubble-user';user.textContent=text;messages.appendChild(user);input.value='';window.setTimeout(function(){var reply=document.createElement('div');reply.className='chat-bubble bubble-bot';reply.textContent='Thanks for the message! Please email me with your timeline and project details.';messages.appendChild(reply);messages.scrollTop=messages.scrollHeight},350)})}());
//
